(()=>{'use strict';if(window.__qpuDbList)return;window.__qpuDbList=true;let busy=false,last=0,all=[],pageNo=1;const pageSize=10;
const rows=x=>Array.isArray(x)?x:Array.isArray(x?.data)?x.data:Array.isArray(x?.rows)?x.rows:[];
function render(){const root=document.querySelector('#purchase'),body=root?.querySelector('.module-shell>.module-body tbody');if(!body)return;const pages=Math.max(1,Math.ceil(all.length/pageSize));pageNo=Math.min(pageNo,pages);body.replaceChildren();all.slice((pageNo-1)*pageSize,pageNo*pageSize).forEach((p,i)=>{const tr=document.createElement('tr');tr.dataset.orderNumber=String(p.purchaseNo||p.no||'');[1+(pageNo-1)*pageSize+i,p.orderDate||'',p.supplier||'',p.item||p.material||'',p.qty??'',p.requestedDueDate||p.due||'',p.status||'',p.iqcStatus||p.iqc||''].forEach(v=>{const td=document.createElement('td');td.textContent=String(v);tr.append(td)});body.append(tr)});let foot=root.querySelector('.qpu-pager');if(!foot){foot=document.createElement('div');foot.className='qpu-pager';body.closest('.module-body').after(foot)}foot.replaceChildren();if(!all.length)return;const count=document.createElement('span');count.textContent='총 '+all.length+'건 · '+pageNo+'/'+pages+' 페이지';foot.append(count);for(let n=1;n<=pages;n++){const b=document.createElement('button');b.type='button';b.textContent=n;b.className=n===pageNo?'active':'';b.onclick=()=>{pageNo=n;render()};foot.append(b)}}
async function load(force=false){const page=document.querySelector('#purchase'),body=page?.querySelector('.module-shell>.module-body tbody');if(!body||busy||(!force&&Date.now()-last<12000))return;busy=true;last=Date.now();let info=page.querySelector('.qpu-db-message');if(!info){info=document.createElement('small');info.className='qpu-db-message';info.style.cssText='display:block;padding:6px 14px;color:#526a83';body.closest('.module-body').before(info)}try{const res=await fetch('/api/purchase-orders',{credentials:'include',cache:'no-store'});const x=await res.json();if(!res.ok||x?.success===false)throw Error(x?.message||'서버 응답 '+res.status);const data=rows(x);all=data;pageNo=1;render();info.textContent=data.length?'총 '+data.length+'건':'등록된 구매발주 내역이 없습니다.'}catch(e){info.textContent='구매발주 DB 조회 불가: '+e.message}finally{busy=false}}
document.addEventListener('click',e=>{if(e.target.closest?.('#qpu-import-dialog .qpi-save'))setTimeout(()=>load(true),1500);if(e.target.closest?.('#purchase .qpu-search,#purchase .qpu-clear'))setTimeout(()=>load(true),300)},true);
const css=document.createElement('style');css.textContent='#purchase .qpu-pager{display:flex;align-items:center;justify-content:center;gap:6px;padding:12px;border:1px solid #d0dcea;border-top:0;background:#fff}#purchase .qpu-pager span{margin-right:12px;font-size:12px;color:#526a83}#purchase .qpu-pager button{border:1px solid #d1dce8;background:#fff;border-radius:5px;min-width:30px;height:28px;cursor:pointer}#purchase .qpu-pager button.active{background:#2563eb;color:#fff;border-color:#2563eb}';document.head.append(css);function applyFilters(){const root=document.querySelector('#purchase');if(!root)return;const q=(root.querySelector('.search-input')?.value||'').trim().toLowerCase(),supplier=(root.querySelector('.qpu-supplier')?.value||'').trim(),status=root.querySelector('.qpu-status')?.value||'',inputs=root.querySelectorAll('.module-toolbar input[type=date]'),start=inputs[0]?.value||'',end=inputs[1]?.value||'';const matching=all.filter(p=>{const txt=[p.purchaseNo,p.supplier,p.item,p.material].join(' ').toLowerCase(),d=p.orderDate||'';return (!q||txt.includes(q))&&(!supplier||p.supplier===supplier)&&(!status||(p.status||'').includes(status))&&(!start||d>=start)&&(!end||d<=end)});const saved=all;all=matching;pageNo=1;render();all=saved}document.addEventListener('input',e=>{if(e.target.closest?.('#purchase .module-toolbar'))applyFilters()},true);document.addEventListener('change',e=>{if(e.target.closest?.('#purchase .module-toolbar'))applyFilters()},true);
new MutationObserver(()=>{const p=document.querySelector('#purchase');if(p?.querySelector('.module-shell>.module-body tbody')&&!p.querySelector('.qpu-db-message'))load()}).observe(document.body,{childList:true,subtree:true});load();
})();